package com.wizzadrds.theworldremembers.voice; import java.io.*;import java.nio.file.*; public final class LocalSttAdapter{private final String executable;public LocalSttAdapter(String executable){this.executable=executable;}public String transcribe(Path audio)throws IOException,InterruptedException{if(!Files.isRegularFile(audio))throw new FileNotFoundException(audio.toString());Process p=new ProcessBuilder(executable,audio.toAbsolutePath().toString()).redirectErrorStream(true).start();String text=new String(p.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8).trim();int code=p.waitFor();if(code!=0)throw new IOException("Local STT exited "+code);return text;}}
